WITH valid_stores AS (SELECT * FROM stores WHERE city = 'London'), stores_stats AS (SELECT CASE WHEN sqft >= 17233 THEN 'high' WHEN sqft >= 6278 THEN 'mid' ELSE 'low' END AS sqft_bucket, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, COUNT(CASE WHEN city = 'London' THEN 1 END) AS london_count, SUM(sqft) AS total_sqft FROM valid_stores GROUP BY CASE WHEN sqft >= 17233 THEN 'high' WHEN sqft >= 6278 THEN 'mid' ELSE 'low' END, DATE_FORMAT(opened_date, 'yyyy-MM')) SELECT sqft_bucket, opened_month, london_count, total_sqft FROM stores_stats WHERE total_sqft > 79000;
